            renderer = QgsSingleSymbolRenderer(symbol)
            layer2.setRenderer(renderer)
            self.assertEqual(layer2.renderer().symbol().color().name(), "#ff0000")

            QgsApplication.processingRegistry().layerPostProcessor().postProcessLayer(
                layer2, "OUTPUT", alg
            )

            self.assertEqual(layer2.renderer().symbol().color().name(), "#123456")

